mapper.select:
SELECT ai.id as albumId,ai.album_title,ai.cover_url,ai.include_track_count,ai.is_finished,ai.status, (SELECT MAX(stat_num) from album_stat where album_id=2 and stat_type='0401') as playStatNum, (SELECT MAX(stat_num) from album_stat where album_id=2 and stat_type='0402') as subscribeStatNum, (SELECT MAX(stat_num) from album_stat where album_id=2 and stat_type='0403') as buyStatNum, (SELECT MAX(stat_num) from album_stat where album_id=2 and stat_type='0404') as ommentStatNum FROM `album_info` ai INNER JOIN album_stat aa on ai.id=aa.album_id and aa.is_deleted=0
and ai.user_id=#{vo.userId}
and ai.status=#{vo.status}
and ai.is_finished=#{vo.isFinished}
and ai.is_deleted=0 GROUP BY ai.id ORDER BY ai.create_time desc
